const LOCALE_STORAGE_KEY = 'tonghong_locale'
const storedLocale =
  typeof localStorage !== 'undefined' ? localStorage.getItem(LOCALE_STORAGE_KEY) : null
const initialLocale = ['id', 'en', 'zh'].includes(storedLocale) ? storedLocale : 'id'

export default createI18n({
  legacy: false,
  locale: initialLocale,
  fallbackLocale: 'en',
  messages,
})
